using System; using Renci.SshNet; class Program { static void Main() { var client = new SshClient("192.168.1.5", "mobile", "123456"); client.Connect(); try { var cmd = client.RunCommand("du -sk /var/mobile/Library/Caches 2>/dev/null | awk '{print $1}'"); Console.WriteLine("OUTPUT:[" + cmd.Result + "]"); Console.WriteLine("ERROR:[" + cmd.Error + "]"); } catch (Exception e) { Console.WriteLine("Ex: " + e.Message); } client.Disconnect(); } }
